saveClient:
function saveClient(S, C, close) {
  const T = C.T, LS_OLD = 'ro-hans.saveUp', LS_LV = 'ro-hans.saveLv', LS_CH = 'ro-hans.saveChest', $ = id => document.getElementById(id);
  S.curT = null; S.curK = null; S.curNat = false; S.fromStash = false;
  // 舊設定（一個開關管卡片＋寶箱）搬過來：舊的打開 → 只開「保存升級選卡」；寶箱照原本當場開。
  //   舊的 key 不刪（退回舊版時還是原本的設定）；新 key 已經有值就不再搬。
  try {
    if (localStorage.getItem(LS_LV) === null) {
      localStorage.setItem(LS_LV, localStorage.getItem(LS_OLD) === '1' ? '1' : '0');
      localStorage.getItem(LS_CH) === null && localStorage.setItem(LS_CH, '0');
    }
  } catch {}
  const get = k => { try { return localStorage.getItem(k) === '1'; } catch { return false; } };
  const put = (k, v) => { try { localStorage.setItem(k, v ? '1' : '0'); } catch {} };
  S.prefLv = () => get(LS_LV); S.prefCh = () => get(LS_CH);
  S.setLv = v => put(LS_LV, v); S.setCh = v => put(LS_CH, v);
  // 可以保存的對局：一般關卡（有首領表），不是故事、無限之塔；PVP／公會戰的場地沒有首領
  S.ok = g => !!(g && g.script && Array.isArray(g.script.bosses) && g.script.bosses.length && !g.isStory && !g.endless);
  // 保存中＝那一種的開關打開，而且不是正在拿出來選（roOpening）
  S.onLv = g => S.ok(g) && S.prefLv() && !g.roOpening;
  S.onCh = g => S.ok(g) && S.prefCh() && !g.roOpening;
  const live = g => g && g.state !== 'over' && S.ok(g);
  let tt = 0;
  const toast = msg => {
    try { const box = $('toasts'); if (!box) return; const d = document.createElement('div'); d.className = 'toast'; d.textContent = msg; box.appendChild(d); clearTimeout(tt); tt = setTimeout(() => d.remove(), 2600); } catch {}
  };
  const cards = g => Math.max(0, g.pendingLevelUps | 0);
  const chests = g => (g.roChests | 0) + (g.roChestKeep ? 1 : 0) + (g.state === 'levelup' && S.curT === 'chest' ? 1 : 0);
  // 「存著的」卡片：玩遊戲中（不是選的畫面、不是等著要開）還留著的 pendingLevelUps 就是存起來的（roLvSaved 記下來）；
  //   自然升級跳出來的那幾張不算。選掉一張就跟著變少（取 min）。
  const savedLv = g => Math.min(g.roLvSaved | 0, cards(g));
  const savedCh = g => (g.roChests | 0) + (g.roChestKeep ? 1 : 0);

  // 寶箱：付錢、存起來（照原本 tryOpenChest 的算法：錢不夠就提示、免費寶箱機率）
  S.stash = (g, e) => {
    const cost = g.chestCost();
    if (g.zeny < cost) { if (g.chestMsgCd <= 0) { g.events.onLoot(T.poor.replace('{h}', g.zeny).replace('{c}', cost)); g.chestMsgCd = 2.5; } return; }
    const o = Math.random() < g.stats.freeChest ? 0 : cost;
    g.zeny -= o; g.chestsOpened++; e.dead = true; g.roChests = (g.roChests | 0) + 1;
    g.events.onLoot(T.stashed.replace('{n}', g.roChests));
    try { g.coop && g.coop.chestOpened(o); } catch {}
    S.sync();
  };
  // curNat＝這個畫面是自然跳出來的（升級／撿到寶箱），不是從存的拿出來的
  S.cur = (g, t, k) => { S.g = g; S.curT = t; S.curK = k; S.curNat = !S.fromStash && !g.roOpening; S.fromStash = false; setTimeout(S.sync, 0); };
  // 拿出來：選卡（有切走時留著的那一組就用它，不重抽）
  S.openLv = g => {
    if (!(g.pendingLevelUps > 0)) return false;
    const k = g.roLvKeep; g.roLvKeep = null;
    g.state = 'levelup'; S.fromStash = true; g.events.onLevelUp(k && k.length ? k : g.rollChoices()); S.fromStash = false;
    return true;
  };
  S.openChest = g => {
    let k = g.roChestKeep; g.roChestKeep = null;
    while (!k && (g.roChests | 0) > 0) { g.roChests--; const s = g.rollChest(); if (s && s.length) k = s; else { g.events.onLoot(T.empty); g.gainExp(30); } }
    if (!k) return false;
    g.openingChest = null; g.openingCost = 0; g.state = 'levelup'; S.fromStash = true; g.events.onChest(k, 0); S.fromStash = false;
    return true;
  };
  // 切走目前的畫面：卡片留著那一組；寶箱留著那一組（現場撿到的寶箱也變成「存著的」，免得站在上面又被開一次、再付一次錢）
  S.park = g => {
    if (S.curT === 'lv') g.roLvKeep = S.curK;
    else if (S.curT === 'chest') { g.roChestKeep = S.curK; if (g.openingChest) { g.openingChest.dead = true; g.openingChest = null; } g.openingCost = 0; }
  };
  S.tab = t => {
    const g = S.g; if (!live(g) || g.state !== 'levelup' || t === S.curT) return;
    if (t === 'chest' ? !((g.roChests | 0) + (g.roChestKeep ? 1 : 0)) : !(g.pendingLevelUps > 0)) return;
    S.park(g); g.roOpening = true;
    (t === 'chest' ? S.openChest(g) : S.openLv(g)) || S.keep();
  };
  // 繼續保存：剩下的都留著，回到遊戲。還有「存著的」卡片／寶箱 → 那一種的開關打開（拆開前是整個打開）；
  //   自然跳出來的那一張／那一個（開關關著時）只是先留著，不幫玩家把開關打開。
  S.keep = () => {
    const g = S.g; if (!live(g)) return;
    const t = S.curT, nat = S.curNat && g.state === 'levelup';
    const lvOther = savedLv(g);
    if (g.state === 'levelup') S.park(g);
    const chOther = (g.roChests | 0) + (g.roChestKeep && !(nat && t === 'chest') ? 1 : 0);
    lvOther > 0 && S.setLv(true); chOther > 0 && S.setCh(true);
    g.roLvSaved = cards(g);
    g.roOpening = false; S.curT = null;
    try { close(); } catch {}
    g.state = 'playing'; toast(T.toastKeep); S.sync();
  };
  // 手動拿出來（HUD 按鈕、B 鍵）：先卡片、再寶箱
  S.openNow = () => {
    const g = S.g; if (!live(g) || g.state !== 'playing' || g.player.dead || g.lootUntil >= 0) return;
    if (!cards(g) && !chests(g)) return;
    g.roOpening = true;
    S.openLv(g) || S.openChest(g) || (g.roOpening = false);
    S.sync();
  };
  // 一張卡／一個寶箱選完、回到遊戲之後：那一種沒在保存 → 繼續拿下一個（寶箱 → 卡片）
  S.after = g => {
    S.curT = null;
    if (!live(g) || g.lootUntil >= 0 || g.player.dead || g.state !== 'playing') { if (g) g.roOpening = false; S.sync(); return; }
    if (!(!S.onCh(g) && S.openChest(g)) && !(!S.onLv(g) && S.openLv(g))) g.roOpening = false;
    S.sync();
  };
  // 打倒尾王：地上的東西吸過來（寶箱、補品、磁鐵不吸）
  S.win = g => {
    try { for (const p of g.pickups) p.dead || p.kind === 'meat' || p.kind === 'chest' || p.kind === 'magnet' || (p.magnet = !0, p.vacuum = !0); } catch (e) { console.warn('[saveup] win', e); }
    g.roChests = 0; g.roLvSaved = 0; g.roLvKeep = g.roChestKeep = null; S.sync();
  };

  function set(kind, on) {
    kind === 'ch' ? S.setCh(on) : S.setLv(on);
    const g = S.g; if (g) g.roOpening = false;
    toast(kind === 'ch' ? (on ? T.toastChOn : T.toastChOff) : (on ? T.toastLvOn : T.toastLvOff)); S.sync();
  }
  function sync() {
    const g = S.g, ok = live(g);
    if (ok && g.state === 'playing' && !g.levelUpQueued && g.pendingLevelUps > 0) g.roLvSaved = g.pendingLevelUps;
    // HUD
    const h = $('sv-hud');
    if (h) {
      const n = ok ? cards(g) : 0, m = ok ? chests(g) : 0;
      const pl = S.prefLv(), pc = S.prefCh();
      const show = ok && g.state === 'playing' && !g.player.dead && g.lootUntil < 0 && (n > 0 || m > 0 || pl || pc);
      h.classList.toggle('hidden', !show);
      if (show) {
        const key = `${n}|${m}|${pl}|${pc}`;
        if (h.dataset.k !== key) {
          h.dataset.k = key;
          // 只列存著的（或正在保存的）那一種
          const parts = [];
          (n > 0 || pl) && parts.push(`${T.tabLv} <b>${n}</b>`);
          (m > 0 || pc) && parts.push(`${T.tabCh} <b>${m}</b>`);
          h.innerHTML = `<span>${n || m ? T.hud : T.hudOn}：${parts.join(' · ')}</span>` + (n || m ? `<button class="ro-btn small" type="button" id="sv-open">${T.open}</button>` : '');
          const b = $('sv-open'); b && b.addEventListener('click', e => { e.stopPropagation(); S.openNow(); });
        }
      }
    }
    // 選的畫面上方的分頁
    const bar = $('sv-bar'), p = $('picker');
    if (bar) {
      const vis = ok && g.state === 'levelup' && p && !p.classList.contains('hidden') && (S.curT === 'lv' || S.curT === 'chest');
      const n = vis ? cards(g) : 0, m = vis ? chests(g) : 0;
      // 有存著的才出現：自然跳出來的畫面 → 另外有存的；從存的拿出來的畫面 → 不只這一個（拆開前兩個都開時一樣）
      const st = vis ? savedLv(g) + savedCh(g) + (!S.curNat && S.curT === 'chest' ? 1 : 0) : 0;
      const show = vis && (g.roOpening || (S.curNat ? st > 0 : st > 1));
      bar.classList.toggle('hidden', !show);
      if (show) {
        const pl = S.prefLv(), pc = S.prefCh();
        const key = `${S.curT}|${n}|${m}|${pl}|${pc}`;
        if (bar.dataset.k !== key) {
          bar.dataset.k = key;
          // 沒有存、也沒在保存的那一種不列分頁（目前畫面那一種一定列）
          bar.innerHTML = (n || pl || S.curT === 'lv' ? `<button class="ro-btn small${S.curT === 'lv' ? ' on' : ''}" data-t="lv" type="button"${n ? '' : ' disabled'}>${T.tabLv} ${n}</button>` : '') +
            (m || pc || S.curT === 'chest' ? `<button class="ro-btn small${S.curT === 'chest' ? ' on' : ''}" data-t="chest" type="button"${m ? '' : ' disabled'}>${T.tabCh} ${m}</button>` : '') +
            `<button class="ro-btn small sv-keep" data-t="keep" type="button">${T.keep}</button>`;
        }
      }
    }
    const c1 = $('sv-check'), c2 = $('sv-check-ch');
    c1 && (c1.checked = S.prefLv()); c2 && (c2.checked = S.prefCh());
  }
  S.sync = sync;
  function build() {
    if (!$('sv-css')) { const s = document.createElement('style'); s.id = 'sv-css'; s.textContent = C.CSS; document.head.appendChild(s); }
    const p = $('picker');
    if (p && !$('sv-bar')) {
      const b = document.createElement('div'); b.id = 'sv-bar'; b.className = 'hidden';
      b.addEventListener('pointerdown', e => e.stopPropagation());
      b.addEventListener('click', e => {
        e.stopPropagation(); const t = e.target && e.target.closest && e.target.closest('button'); if (!t || t.disabled) return;
        t.dataset.t === 'keep' ? S.keep() : S.tab(t.dataset.t);
      });
      const inner = p.querySelector('.pk-inner') || p; inner.insertBefore(b, inner.firstChild);
    }
    if (!$('sv-hud') && document.body) { const h = document.createElement('div'); h.id = 'sv-hud'; h.className = 'hidden'; h.addEventListener('pointerdown', e => e.stopPropagation()); document.body.appendChild(h); }
    const pb = document.querySelector('#pause .ro-body');
    if (pb && !$('sv-pause')) {
      pb.insertAdjacentHTML('beforeend', `<div id="sv-pause">` +
        `<label class="opt-row opt-check"><span><b>${T.rowLv}</b><small>${T.rowLvHint}</small></span><input type="checkbox" id="sv-check"><i class="opt-switch"></i></label>` +
        `<label class="opt-row opt-check"><span><b>${T.rowCh}</b><small>${T.rowChHint}</small></span><input type="checkbox" id="sv-check-ch"><i class="opt-switch"></i></label></div>`);
      $('sv-check').addEventListener('change', e => set('lv', !!e.target.checked));
      $('sv-check-ch').addEventListener('change', e => set('ch', !!e.target.checked));
    }
    sync();
  }
  const watch = () => {
    build();
    for (const k of ['picker', 'pause']) { const el = $(k); el && !el.dataset.svObs && (el.dataset.svObs = '1', new MutationObserver(build).observe(el, { attributes: true, attributeFilter: ['class'] })); }
  };
  document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', watch) : watch();
  setInterval(() => { try { sync(); } catch {} }, 500);   // HUD 數字（很輕：內容沒變就不重畫）
  setInterval(watch, 3000);                              // 遊戲重建畫面後補掛
  // B 鍵：拿出來選（打字時不算）
  window.addEventListener('keydown', e => {
    if (e.repeat || e.ctrlKey || e.altKey || e.metaKey || (e.key !== 'b' && e.key !== 'B')) return;
    const a = document.activeElement; if (a && (a.tagName === 'INPUT' || a.tagName === 'TEXTAREA' || a.isContentEditable)) return;
    const g = S.g; if (!live(g) || g.state !== 'playing') return;
    S.openNow();
  });
}
